use std::cmp::Ordering;
fn main() {
    let n = 50u32;
    let mut v: Vec<u32> = (0..n).map(|i| (i * 7919) % n).collect();
    // rock-paper-scissors on residues mod 3: not transitive, so not a total order
    v.sort_by(|a, b| match (a % 3 + 3 - b % 3) % 3 {
        0 => Ordering::Equal,
        1 => Ordering::Greater,
        _ => Ordering::Less,
    });
    println!("returned");
}

