fn classify(s: Option<&str>) -> &'static str {
    match s {
        Some(t) if let Ok(n) = t.parse::<i32>() && n > 0 => "positive number",
        Some(_) => "other text",
        None => "nothing",
    }
}
fn main() {
    println!("{} / {} / {}", classify(Some("5")), classify(Some("x")), classify(None));
}

