const BODY_STRIDE: usize = 17;
fn body_at(i: usize) -> [f64; BODY_STRIDE] {
    let mut b = [0.0; BODY_STRIDE];
    b[9] = 1.0; // qw
    b[13] = 0.5; // hx
    b[16] = i as f64; // mode
    b
}
fn main() {
    let [x, y, z, _vx, _vy, _vz, _qx, _qy, _qz, qw, _wx, _wy, _wz, hx, _hy, _hz, mode] = body_at(2);
    println!("pos=({x},{y},{z}) qw={qw} hx={hx} mode={mode}");
}

